function showPoints(){pickCtx.clearRect(0,0,1920,1080);pickCtx.font='28px Arial';points.forEach((p,i)=>{pickCtx.fillStyle='#ffda78';pickCtx.beginPath();pickCtx.arc(...p.image,8,0,7);pickCtx.fill();pickCtx.fillText(String(i+1),p.image[0]+12,p.image[1]-12);});$('#point-list').textContent=points.map((p,i)=>`${i+1}: FIELD ${p.field.join(', ')} → IMAGE ${p.image.map(Math.round).join(', ')}`).join(' | ');}
function clearCalibration(reason){if(current().kind!=='synthetic')current().h=null;points=[];picking=false;stage.classList.remove('calibrating');showPoints();if(reason)message(reason);send();}
function detach(){video.pause();video.srcObject=null;video.removeAttribute('src');video.load();}
function showSource(){sourceReady=false;epoch++;const c=current();detach();points=c.points||[];showPoints();video.style.display=c.kind==='synthetic'?'none':'block';synthetic.style.display=c.kind==='synthetic'?'block':'none';$('#source-status').textContent=c.name;if(c.kind==='synthetic'){sourceReady=true;drawDemo();}else if(c.kind==='file'&&c.url){video.src=c.url;video.load();}else if(c.kind==='camera'&&c.stream){video.srcObject=c.stream;video.play().catch(e=>message('Click Play to start camera: '+e.message,true));}else message('Select a local video or connect a camera for this slot.',true);send();}
video.onloadeddata=()=>{sourceReady=true;$('#source-status').textContent=`${current().name} · ${video.videoWidth} × ${video.videoHeight} · ready`;send();};
video.onloadedmetadata=()=>{if(current().kind==='file'&&current().time>0&&current().time<video.duration)video.currentTime=current().time;};
video.onerror=()=>{sourceReady=false;const codes={1:'Playback was interrupted',2:'Unable to read the selected file',3:'Browser could not decode this video codec',4:'Unsupported video codec or damaged file'};message((codes[video.error?.code]||'Video could not load')+'. Try an H.264 MP4 or VP9 WebM. No upload server is involved.',true);$('#source-status').textContent='VIDEO ERROR';send();};
